                    if (String(url).match(/^(\/|.:\\)/)) {
                        // absolute local path
                    } else if (!String(url).startsWith('http')) {
                        url = URL.root.withFilename(url).withRelativePartsResolved();
                    }
                    editor.openURL(url);
