                        var widthAttr = rawNodeInfo.attributes.detect(function (ea) {
                            return ea.key === 'width';
                        });
                        var heightAttr = rawNodeInfo.attributes.detect(function (ea) {
                            return ea.key === 'height';
                        });
                        if (widthAttr && heightAttr) obj._Extent = this.registerWithPlugins(pt(Number(widthAttr.value), Number(heightAttr.value)), [new ClassPlugin()]);

                        var attr = rawNodeInfo.attributes.detect(function (ea) {
                            return ea.key === 'fill-opacity';
                        });
                        obj._FillOpacity = attr && Number(attr.value);
                        var attr = rawNodeInfo.attributes.detect(function (ea) {
                            return ea.key === 'stroke-opacity';
                        });
                        obj._StrokeOpacity = attr && Number(attr.value);
                        var attr = rawNodeInfo.attributes.detect(function (ea) {
                            return ea.key === 'stroke-width';
                        });
                        obj._BorderWidth = attr && Number(attr.value);
