    "lively.ide.execShellCommand": {
      description: "execute shell command",
      exec: function exec(codeEditor, args) {
        var insertResult = !args || typeof args.insert === "undefined" || !!args.insert,
            showProgress = args && !!args.showProgress,
            openInWindow = !codeEditor || args && args.count !== 4 /*universal argument*/
        ,
            addToHistory = args && args.addToHistory,
            group = args && args.group || "interactive-shell-command",
            editor;

        var cmdString = args && args.shellCommand;
        if (cmdString) runCommand(cmdString);else {
          $world.prompt("Enter shell command to run.", function (cmdString) {
            if (!cmdString) show("No command entered, aborting...!");else runCommand(cmdString);
          }, { historyId: "lively.ide.execShellCommand" }).panel.focus();
        }

        // -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-

        function ensureCodeEditor(title) {
          if (editor) return editor;
          if (!openInWindow && codeEditor && codeEditor.isCodeEditor) return codeEditor;
          var ed = $world.addCodeEditor({
            title: "shell command: " + title,
            gutter: false,
            textMode: "text",
            extent: pt(400, 500),
            position: "center"
          });
          ed.owner.comeForward();
          return editor = ed;
        }

        function runCommand(command) {
          var ed = ensureCodeEditor(command),
              mergeUndos,
              connections = [],
              title = ed.getWindow().getTitle(),
              cmd = ed.currentShellCommand,
              msgMorph;

          if (cmd) {
            lively.bindings.once(cmd, "end", lively.ide.commands, "exec", {
              updater: function updater($upd) {
                (function () {
                  $upd("lively.ide.execShellCommand", ed, args);
                }).delay(0);
              },
              varMapping: { ed: ed, args: args }
            });

            return;
          }

          if (ed.getWindow()) ed.getWindow().setTitle("[running] " + title);

          ed.hasOwnProperty("doNotSerialize") ? ed.doNotSerialize.pushIfNotIncluded("currentShellCommand") : ed.doNotSerialize = ["currentShellCommand"];

          cmd = ed.currentShellCommand = lively.shell.run(command, { addToHistory: addToHistory, group: group }, function (err, cmd) {
            ed.currentShellCommand = null;
            connections.invoke("disconnect");
            var result = cmd.resultString(true);

            if (!showProgress && insertResult) ed.printObject(null, result);
            if (msgMorph) {
              msgMorph.insertion = result;
              msgMorph.appendRichText((msgMorph.textString.endsWith("\n") ? "" : "\n") + "Exited with " + cmd.getCode());
              msgMorph.enableRemoveOnTargetMorphChange();
              msgMorph.ensureOpenFor(ed);
            }
            if (ed.getWindow()) ed.getWindow().setTitle(title);

            mergeUndos && mergeUndos();
          });

          if (insertResult) {
            ed.mergeUndosOf(function (triggerMerge) {
              mergeUndos = triggerMerge;
              if (showProgress) {
                ed.collapseSelection("end");
                ed.addScript(function insertAndGrowSelection(string) {
                  var rangeBefore = this.getSelectionRangeAce();
                  this.printObject(null, string);
                  var rangeAfter = this.getSelectionRangeAce();
                  this.setSelectionRangeAce({
                    start: rangeBefore.start,
                    end: rangeAfter.end
                  });
                });
                connections.pushAll([lively.bindings.connect(cmd, "stdout", ed, "insertAtCursor", {
                  updater: function updater($upd, string) {
                    $upd(string, false, false, true);
                  }
                }), lively.bindings.connect(cmd, "stderr", ed, "insertAtCursor", {
                  updater: function updater($upd, string) {
                    $upd(string, false, false, true);
                  }
                })]);
              }
            });
          } else {
            if (showProgress) {
              // show progress in status message morph, don't modify source text
              msgMorph = ed.ensureStatusMessageMorph({ fontSize: 9 });
              msgMorph.disableRemoveOnTargetMorphChange();
              if (!msgMorph.owner) ed.setStatusMessage("");

              var connectionSpec = {
                updater: function updater($upd, newContent) {
                  if (!this.targetObj.textString.length) newContent = newContent.trimLeft();
                  if (this.targetObj.textString.length > 1000) {
                    newContent = "...";
                    connections.invoke("disconnect");
                  }
                  $upd(newContent, {});
                  this.targetObj.alignAtBottomOf(ed);
                },
                varMapping: { ed: ed, connections: connections }
              };

              connections.pushAll([lively.bindings.connect(cmd, "stdout", msgMorph, "appendRichText", connectionSpec), lively.bindings.connect(cmd, "stderr", msgMorph, "appendRichText", connectionSpec)]);
            }
          }
        }
      }
    },
