      var chip = new lively.morphic.Box(lively.rect(pad, chipY, size * 2, size));
      chip.setFill(originalFill instanceof Color ? originalFill : Color.white);
      chip.setBorderWidth(1);
      chip.setBorderColor(Color.gray);
      panel.addMorph(chip);

