module('lively.Ometa').requires('lively.Network', 'ometa.lively').toRun(function () {

    /*
        An OMeta Workspace like http://www.cs.ucla.edu/~awarth/ometa/.
        Uses Alessandro Warth OMeta-js 2 to evalute text.
    */
    Object.subclass('OMetaSupport');

    Object.extend(OMetaSupport, {

        ometaGrammarDir: URL.codeBase,

        fromFile: function fromFile(fileName) {
            var src = OMetaSupport.fileContent(fileName),
                grammar = OMetaSupport.ometaEval(src);
            return grammar;
        },

        translateAndWrite: function translateAndWrite(sourceFileName, destFileName, additionalRequirements) {
            var requirementsString = additionalRequirements ? ",'" + additionalRequirements.join("','") + "'" : "",
                str = Strings.format('module(\'%s\').requires(\'ometa.lively\'%s).toRun(function() {\n%s\n});', destFileName.replace(/\.js$/, '').replace(/\//g, '.'), requirementsString, OMetaSupport.translateToJs(OMetaSupport.fileContent(sourceFileName)));
            OMetaSupport.writeGrammar(destFileName, str);
            lively.morphic.World.current().setStatusMessage(Strings.format('Successfully compiled OMeta grammar %s to %s', sourceFileName, destFileName), Color.green, 3);
        },
        translate: function translate(source, additionalRequirements, destFileName) {
            destFileName = destFileName || 'anonymousOMetaModule';
            var requirementsString = additionalRequirements ? ",'" + additionalRequirements.join("','") + "'" : "",
                str = Strings.format('module(\'%s\').requires(\'ometa.lively\'%s).toRun(function() {\n%s\n});', destFileName.replace(/\.js$/, '').replace(/\//g, '.'), requirementsString, OMetaSupport.translateToJs(source));
            lively.morphic.World.current().setStatusMessage(Strings.format('Successfully compiled OMeta grammar %s', source.truncate(300)), Color.green, 3);
            return str;
        },

        ometaEval: function ometaEval(src) {
            var jsSrc = OMetaSupport.translateToJs(src);
            return eval(jsSrc);
        },

        translateToJs: function translateToJs(src) {
            var ometaSrc = OMetaSupport.matchAllWithGrammar(BSOMetaJSParser, "topLevel", src);
            if (!ometaSrc) throw new Error('Problem in translateToJs: Cannot create OMeta Ast from source');
            var jsSrc = OMetaSupport.matchWithGrammar(BSOMetaJSTranslator, "trans", ometaSrc);
            if (/\"\\\\[rn]\"/.test(jsSrc)) {
                jsSrc = jsSrc.replace(/\"\\\\n\"/g, '"\\n"').replace(/\"\\\\r\"/g, '"\\r"');
                alertDbg("OMetaSupport.translate.js: Fixed doubly-escaped line end chars");
            }
            return jsSrc;
        },

        matchAllWithGrammar: function matchAllWithGrammar(grammar, rule, src, errorHandling) {
            // errorHandling can be undefined or a callback or true (own error handle is used)
            var errorFunc;
            if (!errorHandling) errorFunc = OMetaSupport.handleErrorDebug;else if (errorHandling instanceof Function) errorFunc = errorHandling;else errorFunc = OMetaSupport.handleErrorDebug;
            return grammar.matchAll(src, rule, null, errorFunc.curry(src, rule));
        },

        matchWithGrammar: function matchWithGrammar(grammar, rule, src, errorHandling) {
            // errorHandling can be undefined or a callback or true (own error handle is used)
            var errorFunc;
            if (!errorHandling) errorFunc = OMetaSupport.handleErrorDebug;else if (errorHandling instanceof Function) errorFunc = errorHandling;else errorFunc = OMetaSupport.handleErrorDebug;
            return grammar.match(src, rule, null, errorFunc.curry(src, rule));
        },

        handleErrorDebug: function handleErrorDebug(src, rule, grammarInstance, errorIndex) {
            var charsBefore = 500,
                charsAfter = 250,
                msg = 'OMeta Error -- ' + rule + '\n',
                startIndex = Math.max(0, errorIndex - charsBefore),
                stopIndex = Math.min(src.length, errorIndex + charsAfter);

            //console.log('Last twenty Rules: ' + grammarInstance._ruleStack && grammarInstance._ruleStack.slice(grammarInstance._ruleStack.length-20));
            msg += src.constructor === Array ? 'src = [' + src.toString() + ']' : src.substring(startIndex, errorIndex) + '<--Error-->' + src.substring(errorIndex, stopIndex);
            console.log(msg);
            return msg;
        },

        handleError: function handleError(src, rule, grammarInstance, errorIndex) {},

        fileContent: function fileContent(fileName) {
            var url = URL.root.withFilename(fileName);
            return new WebResource(url).get().content;
        },

        writeGrammar: function writeGrammar(fileName, src) {
            var url = URL.root.withFilename(fileName);
            return new WebResource(url).put(src);
        }
    });
});
